pub fn atoi_like(input: &str) -> i32 {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let mut sign = 1i64;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                sign = -1;
                index += 1;
            }
            _ => {}
        }
    }

    let mut value = 0i64;
    let mut saw_digit = false;
    while index < bytes.len() && bytes[index].is_ascii_digit() {
        saw_digit = true;
        value = value * 10 + i64::from(bytes[index] - b'0');
        index += 1;
    }

    if !saw_digit {
        return 0;
    }

    let signed = value * sign;
    if signed > i64::from(i32::MAX) {
        i32::MAX
    } else if signed < i64::from(i32::MIN) {
        i32::MIN
    } else {
        signed as i32
    }
}

pub fn ordinalize(number: i32) -> String {
    let suffix = if (11..=13).contains(&(number % 100)) {
        "th"
    } else {
        match number % 10 {
            1 => "st",
            2 => "nd",
            3 => "rd",
            _ => "th",
        }
    };

    format!("{number}{suffix}")
}

