pub fn pluralize(word: &str) -> String {
    let mut result = String::with_capacity(word.len() + 1);
    result.push_str(word);
    result.push('s');
    result
}

pub fn camelize(word: &str, lowercase_first_letter: bool) -> String {
    let mut result = String::with_capacity(word.len());
    let mut uppercase_next = !lowercase_first_letter;

    for ch in word.chars() {
        if ch == '_' {
            uppercase_next = true;
            continue;
        }

        if uppercase_next {
            result.push(ch.to_ascii_uppercase());
            uppercase_next = false;
        } else {
            result.push(ch);
        }
    }

    result
}

pub fn titleize(word: &str) -> String {
    let mut result = String::with_capacity(word.len());
    let mut at_word_start = true;

    for ch in word.chars() {
        if at_word_start {
            result.push(ch.to_ascii_uppercase());
        } else {
            result.push(ch.to_ascii_lowercase());
        }
        at_word_start = ch == ' ';
    }

    result
}

pub fn capitalize(word: &str) -> String {
    let mut chars = word.chars();
    let Some(first) = chars.next() else {
        return String::new();
    };

    let mut result = String::with_capacity(word.len());
    result.push(first.to_ascii_uppercase());
    for ch in chars {
        result.push(ch.to_ascii_lowercase());
    }
    result
}

pub fn truncate(word: &str, length: usize, omission: &str) -> String {
    let word_len = word.chars().count();
    if word_len <= length {
        return word.to_owned();
    }

    if length == 0 {
        return String::new();
    }

    let omission_len = omission.chars().count();
    if omission_len >= length {
        return omission.chars().take(length).collect();
    }

    let keep = length - omission_len;
    let mut result: String = word.chars().take(keep).collect();
    result.push_str(omission);
    result
}

pub fn parameterize(word: &str, separator: &str) -> String {
    let mut result = String::new();

    for ch in word.chars() {
        if ch.is_ascii_alphanumeric() {
            result.push(ch.to_ascii_lowercase());
        } else if ch == ' ' {
            result.push_str(separator);
        }
    }

    result
}

pub fn is_plural(word: &str) -> bool {
    word.ends_with('s')
}

